"""Bounded community-based column ordering for character-prefix reuse."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Preserve values while selecting a bounded, exact-scored column order."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recently returned orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert a scalar to evaluator text without changing source values."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Score sorted adjacent serialized strings by their character LCP sum."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified labels to source positions."""
        result = {}
        for i, value in enumerate(columns):
            result.setdefault(str(value), []).append(i)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build connected merge blocks in source-column order."""
        parent = list(range(width))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(g) for g in groups.values()), key=lambda g: g[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Apply dependency and merge precedence to a proposed permutation."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {value: i for i, value in enumerate(preference)}
        heap = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(heap)

        answer = []
        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))

        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Return length-weighted pair repetition, repetition, and mass statistics."""
        result = []
        for col in range(text.shape[1]):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @staticmethod
    def _affinity(text, left, right):
        """Measure repeated right values conditional on a left value."""
        groups = {}
        for row in range(text.shape[0]):
            groups.setdefault(text[row, left], []).append(row)

        total = 0
        for members in groups.values():
            if len(members) < 2:
                continue
            counts = {}
            for row in members:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                total += len(value) * count * (count - 1)
        return total

    @classmethod
    def _community_orders(cls, text, stats, blocks):
        """Construct two bounded community orientations from conditional affinities."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[c][0] for c in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:24]

        # Each block contributes at most two fields, bounding affinity work.
        affinity = {}
        for i in active:
            for j in active:
                if i != j:
                    affinity[i, j] = sum(
                        cls._affinity(text, a, b)
                        for a in blocks[i][:2]
                        for b in blocks[j][:2]
                    )

        symmetric = {}
        for p, i in enumerate(active):
            for j in active[p + 1:]:
                symmetric[i, j] = affinity[i, j] + affinity[j, i]

        unused = set(active)
        communities = []
        for _ in range(6):
            choices = [
                (value, -i, -j, i, j)
                for (i, j), value in symmetric.items()
                if i in unused and j in unused and value > 0
            ]
            if not choices:
                break

            _, _, _, first, second = max(choices)
            group = [first, second]
            unused.remove(first)
            unused.remove(second)

            while len(group) < 4:
                additions = []
                for candidate in unused:
                    gain = sum(
                        symmetric.get(
                            tuple(sorted((candidate, member))), 0
                        )
                        for member in group
                    )
                    if gain > 0:
                        additions.append(
                            (gain, mass[candidate], -candidate, candidate)
                        )
                if not additions:
                    break
                candidate = max(additions)[3]
                group.append(candidate)
                unused.remove(candidate)
            communities.append(group)

        communities.extend(
            [[i] for i in sorted(
                unused, key=lambda i: (-mass[i], blocks[i][0])
            )]
        )

        def orient(group, reverse=False):
            """Greedily build a directed affinity chain for one community."""
            if len(group) <= 1:
                return list(group)
            remaining = set(group)
            start = max(remaining, key=lambda i: (mass[i], -i))
            path = [start]
            remaining.remove(start)
            while remaining:
                last = path[-1]
                if reverse:
                    key = lambda i: (affinity.get((i, last), 0), mass[i], -i)
                else:
                    key = lambda i: (affinity.get((last, i), 0), mass[i], -i)
                nxt = max(remaining, key=key)
                path.append(nxt)
                remaining.remove(nxt)
            return path

        oriented = []
        for group in communities:
            forward = orient(group)
            reverse = orient(group, True)
            fs = sum(
                affinity.get((a, b), 0)
                for a, b in zip(forward, forward[1:])
            )
            rs = sum(
                affinity.get((a, b), 0)
                for a, b in zip(reverse, reverse[1:])
            )
            oriented.append(forward if fs >= rs else reverse)

        oriented.sort(key=lambda g: (-sum(mass[i] for i in g), g[0]))

        first = [
            column
            for group in oriented
            for block in group
            for column in blocks[block]
        ]
        second = [
            column
            for group in reversed(oriented)
            for block in reversed(group)
            for column in blocks[block]
        ]
        return [first, second]

    @staticmethod
    def _serialize(text, order):
        """Serialize every source row under one column permutation."""
        return [
            "".join(text[row, column] for column in order)
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized text and return value-preserving output."""
        row_order = sorted(
            range(len(serialized)),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            values[output_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        return (
            pd.DataFrame(
                values,
                index=df.index.take(row_order),
                columns=list(df.columns),
            ),
            public_orders,
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate global and community orders using the exact LCP objective."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline] + self._community_orders(text, stats, blocks)
        best_score = -1
        best_order = None
        best_serialized = None

        for preference in preferences[:3]:
            order = self._repair(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        result, public_orders = self._materialize(
            df,
            source,
            best_order,
            best_serialized,
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

